namespace sv_cf1ef7d3954c47409a98c9d9592ce3ad.Services;

public class MockSettingsService : ISettingsService
{
    private UserProfile _profile = new("Jane Doe", "jane@example.com", "https://i.pravatar.cc/150?img=5", "Full-stack developer who loves Blazor and open source.");
    private NotificationPrefs _notificationPrefs = new(true, false, true, ["announcements", "marketing"]);
    private SecuritySettings _securitySettings = new(false, DateTime.UtcNow.AddDays(-45), [
        new("sess-1", "Chrome on Windows", "New York, US", DateTime.UtcNow.AddMinutes(-5)),
        new("sess-2", "Firefox on macOS", "London, UK", DateTime.UtcNow.AddHours(-3)),
        new("sess-3", "Safari on iPhone", "Tokyo, JP", DateTime.UtcNow.AddDays(-2)),
    ]);
    private AppearanceSettings _appearance = new("Light", "Medium", "English", false);

    private static readonly List<string> AllChannels = ["general", "announcements", "engineering", "marketing", "support", "random"];

    public Task<UserProfile> GetProfileAsync() => Task.FromResult(_profile);

    public Task SaveProfileAsync(UserProfile profile)
    {
        _profile = profile;
        return Task.CompletedTask;
    }

    public Task<NotificationPrefs> GetNotificationPrefsAsync()
    {
        var prefs = _notificationPrefs with
        {
            MutedChannels = AllChannels
                .Where(c => _notificationPrefs.MutedChannels.Contains(c))
                .Concat(AllChannels.Where(c => !_notificationPrefs.MutedChannels.Contains(c)))
                .ToList()
        };
        // Return all channels; muted ones are tracked in the MutedChannels list
        return Task.FromResult(_notificationPrefs);
    }

    public Task SaveNotificationPrefsAsync(NotificationPrefs prefs)
    {
        _notificationPrefs = prefs;
        return Task.CompletedTask;
    }

    public Task<SecuritySettings> GetSecuritySettingsAsync() => Task.FromResult(_securitySettings);

    public Task ChangePasswordAsync(string currentPassword, string newPassword)
    {
        if (string.IsNullOrWhiteSpace(currentPassword))
            throw new InvalidOperationException("Current password is required.");
        _securitySettings = _securitySettings with { LastPasswordChange = DateTime.UtcNow };
        return Task.CompletedTask;
    }

    public Task RevokeSessionAsync(string sessionId)
    {
        _securitySettings = _securitySettings with
        {
            Sessions = _securitySettings.Sessions.Where(s => s.Id != sessionId).ToList()
        };
        return Task.CompletedTask;
    }

    public Task<AppearanceSettings> GetAppearanceAsync() => Task.FromResult(_appearance);

    public Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        _appearance = settings;
        return Task.CompletedTask;
    }

    public static List<string> GetAllChannels() => AllChannels;
}

