@* Vertical sidebar navigation for settings sections *@

<nav class="settings-sidebar">
    <h5 class="px-3 py-2 text-muted text-uppercase fw-semibold" style="font-size: 0.75rem; letter-spacing: 0.05em;">Settings</h5>
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
                <button class="nav-link w-100 text-start d-flex align-items-center gap-2 @(ActiveSection == section.Key ? "active" : "")"
                        @onclick="() => OnSectionChanged.InvokeAsync(section.Key)">
                    <span>@section.Icon</span>
                    <span>@section.Label</span>
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired] public string ActiveSection { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnSectionChanged { get; set; }

    private record SectionItem(string Key, string Label, string Icon);

    private static readonly SectionItem[] Sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨"),
    ];
}

@using sv_cf1ef7d3954c47409a98c9d9592ce3ad.Services

<div class="settings-section">
    <h4 class="mb-4">Profile</h4>

    @if (Profile is not null)
    {
        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label fw-semibold">Display Name</label>
                    <input type="text" class="form-control" @bind="editName" />
                </div>
                <div class="mb-3">
                    <label class="form-label fw-semibold">Email</label>
                    <input type="email" class="form-control" @bind="editEmail" />
                </div>
                <div class="mb-3">
                    <label class="form-label fw-semibold">Bio</label>
                    <textarea class="form-control" rows="4" @bind="editBio"></textarea>
                </div>
            </div>
            <div class="col-md-4 text-center">
                <div class="mb-2">
                    <img src="@Profile.AvatarUrl" alt="Avatar" class="rounded-circle border" width="120" height="120"
                         style="object-fit: cover;" />
                </div>
                <small class="text-muted text-break">@Profile.AvatarUrl</small>
            </div>
        </div>

        <div class="d-flex gap-2 mt-3">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
                @if (saving)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@saving">
                Discard Changes
            </button>
        </div>

        @if (!string.IsNullOrEmpty(successMessage))
        {
            <div class="alert alert-success alert-dismissible fade show mt-3" role="alert">
                @successMessage
                <button type="button" class="btn-close" @onclick="() => successMessage = null"></button>
            </div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public UserProfile? Profile { get; set; }
    [Parameter, EditorRequired] public EventCallback<UserProfile> OnSave { get; set; }

    private string editName = "";
    private string editEmail = "";
    private string editBio = "";
    private bool saving;
    private string? successMessage;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !saving)
        {
            ResetForm();
        }
    }

    private void ResetForm()
    {
        editName = Profile!.DisplayName;
        editEmail = Profile.Email;
        editBio = Profile.Bio;
    }

    private async Task SaveAsync()
    {
        saving = true;
        successMessage = null;
        var updated = Profile! with { DisplayName = editName, Email = editEmail, Bio = editBio };
        await OnSave.InvokeAsync(updated);
        successMessage = "Profile saved successfully!";
        saving = false;
    }

    private void Discard()
    {
        ResetForm();
        successMessage = null;
    }
}

@using sv_cf1ef7d3954c47409a98c9d9592ce3ad.Services

<div class="settings-section">
    <h4 class="mb-4">Notifications</h4>

    @if (Prefs is not null)
    {
        <div class="mb-4">
            <h6 class="fw-semibold mb-3">Notification Channels</h6>

            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="emailNotif" checked="@emailNotif" @onchange="e => emailNotif = (bool)e.Value!" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="pushNotif" checked="@pushNotif" @onchange="e => pushNotif = (bool)e.Value!" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" checked="@weeklyDigest" @onchange="e => weeklyDigest = (bool)e.Value!" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>
        </div>

        <div class="mb-4">
            <h6 class="fw-semibold mb-3">Muted Channels</h6>
            <p class="text-muted small">Check channels you want to mute.</p>

            @foreach (var channel in AllChannels)
            {
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                           checked="@mutedChannels.Contains(channel)"
                           @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                    <label class="form-check-label" for="@($"ch-{channel}")">
                        #@channel
                    </label>
                </div>
            }
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
            @if (saving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save Preferences
        </button>

        @if (!string.IsNullOrEmpty(successMessage))
        {
            <div class="alert alert-success alert-dismissible fade show mt-3" role="alert">
                @successMessage
                <button type="button" class="btn-close" @onclick="() => successMessage = null"></button>
            </div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public NotificationPrefs? Prefs { get; set; }
    [Parameter, EditorRequired] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private static readonly string[] AllChannels = ["general", "announcements", "engineering", "marketing", "support", "random"];

    private bool emailNotif;
    private bool pushNotif;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private bool saving;
    private string? successMessage;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !saving)
        {
            emailNotif = Prefs.EmailNotifications;
            pushNotif = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = new HashSet<string>(Prefs.MutedChannels);
        }
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        saving = true;
        successMessage = null;
        var updated = new NotificationPrefs(emailNotif, pushNotif, weeklyDigest, mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        successMessage = "Notification preferences saved!";
        saving = false;
    }
}

@using sv_cf1ef7d3954c47409a98c9d9592ce3ad.Services

@if (Visible && Session is not null)
{
    <div class="modal-backdrop fade show"></div>
    <div class="modal fade show d-block" tabindex="-1" role="dialog">
        <div class="modal-dialog modal-dialog-centered" role="document">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="OnCancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke this session?</p>
                    <ul class="list-unstyled mb-0">
                        <li><strong>Device:</strong> @Session.Device</li>
                        <li><strong>Location:</strong> @Session.Location</li>
                        <li><strong>Last Active:</strong> @Session.LastActive.ToString("g")</li>
                    </ul>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary" @onclick="OnCancel">Cancel</button>
                    <button type="button" class="btn btn-danger" @onclick="OnConfirm">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public bool Visible { get; set; }
    [Parameter] public ActiveSession? Session { get; set; }
    [Parameter, EditorRequired] public EventCallback OnConfirm { get; set; }
    [Parameter, EditorRequired] public EventCallback OnCancel { get; set; }
}

@using sv_cf1ef7d3954c47409a98c9d9592ce3ad.Services

<div class="settings-section">
    <h4 class="mb-4">Security</h4>

    @if (Settings is not null)
    {
        <ChangePasswordPanel OnChangePassword="OnChangePassword" />

        <div class="card mb-3">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <h6 class="mb-1">Two-Factor Authentication</h6>
                    <span class="badge @(Settings.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                    @if (Settings.LastPasswordChange.HasValue)
                    {
                        <small class="text-muted ms-2">
                            Last password change: @Settings.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                        </small>
                    }
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" checked="@twoFactorEnabled"
                           @onchange="Toggle2FA" />
                </div>
            </div>
        </div>

        <div class="card">
            <div class="card-header fw-semibold">Active Sessions</div>
            <div class="card-body p-0">
                <div class="table-responsive">
                    <table class="table table-hover mb-0">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th class="text-end">Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in Settings.Sessions)
                            {
                                var isCurrent = session == Settings.Sessions.FirstOrDefault();
                                <tr>
                                    <td>
                                        @session.Device
                                        @if (isCurrent)
                                        {
                                            <span class="badge bg-primary ms-1">Current</span>
                                        }
                                    </td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td class="text-end">
                                        @if (!isCurrent)
                                        {
                                            <button class="btn btn-outline-danger btn-sm" @onclick="() => PromptRevoke(session)">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            </div>
        </div>

        <RevokeSessionDialog Visible="@showRevokeDialog"
                             Session="@sessionToRevoke"
                             OnConfirm="ConfirmRevokeAsync"
                             OnCancel="CancelRevoke" />
    }
</div>

@code {
    [Parameter, EditorRequired] public SecuritySettings? Settings { get; set; }
    [Parameter, EditorRequired] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter, EditorRequired] public EventCallback<bool> OnToggle2FA { get; set; }

    private bool twoFactorEnabled;
    private bool showRevokeDialog;
    private ActiveSession? sessionToRevoke;

    protected override void OnParametersSet()
    {
        if (Settings is not null)
            twoFactorEnabled = Settings.TwoFactorEnabled;
    }

    private async Task Toggle2FA(ChangeEventArgs e)
    {
        twoFactorEnabled = (bool)e.Value!;
        await OnToggle2FA.InvokeAsync(twoFactorEnabled);
    }

    private void PromptRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeDialog = true;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(sessionToRevoke.Id);
        }
        showRevokeDialog = false;
        sessionToRevoke = null;
    }

    private void CancelRevoke()
    {
        showRevokeDialog = false;
        sessionToRevoke = null;
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@using sv_cf1ef7d3954c47409a98c9d9592ce3ad.Services

<div class="settings-section">
    <h4 class="mb-4">Appearance</h4>

    @if (Settings is not null)
    {
        <div class="row">
            <div class="col-md-7">
                <div class="mb-4">
                    <h6 class="fw-semibold mb-3">Theme</h6>
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
