toolArgs.file_text:
@using sv_cf1ef7d3954c47409a98c9d9592ce3ad.Services

<div class="settings-section">
    <h4 class="mb-4">Appearance</h4>

    @if (Settings is not null)
    {
        <div class="row">
            <div class="col-md-7">
                <div class="mb-4">
                    <h6 class="fw-semibold mb-3">Theme</h6>
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                                   value="@theme" checked="@(editTheme == theme)"
                                   @onchange="() => editTheme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <h6 class="fw-semibold mb-3">Font Size</h6>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                                   value="@size" checked="@(editFontSize == size)"
                                   @onchange="() => editFontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <h6 class="fw-semibold mb-3">Language</h6>
                    <select class="form-select" style="max-width: 250px;" @bind="editLanguage">
                        @foreach (var lang in Languages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>

                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode"
                               checked="@editCompactMode"
                               @onchange="e => editCompactMode = (bool)e.Value!" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
                    @if (saving)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Save
                </button>

                @if (!string.IsNullOrEmpty(successMessage))
                {
                    <div class="alert alert-success alert-dismissible fade show mt-3" role="alert">
                        @successMessage
                        <button type="button" class="btn-close" @onclick="() => successMessage = null"></button>
                    </div>
                }
            </div>

            <div class="col-md-5">
                <h6 class="fw-semibold mb-3">Live Preview</h6>
                <div class="border rounded p-3 @PreviewBgClass" style="@PreviewStyle">
                    <div class="@(editCompactMode ? "mb-1" : "mb-3")">
                        <strong style="@PreviewHeadingStyle">Dashboard</strong>
                    </div>
                    <p style="@PreviewTextStyle" class="@(editCompactMode ? "mb-1" : "mb-2")">
                        This is how your content will appear with the selected settings.
                    </p>
                    <div class="d-flex gap-2">
                        <span class="badge @PreviewBadgeClass">Active</span>
                        <span class="badge bg-secondary">Draft</span>
                    </div>
                    <hr />
                    <small class="@PreviewMutedClass">
                        Language: @editLanguage &middot; Compact: @(editCompactMode ? "On" : "Off")
                    </small>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings? Settings { get; set; }
    [Parameter, EditorRequired] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private static readonly string[] Languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    private string editTheme = "Light";
    private string editFontSize = "Medium";
    private string editLanguage = "English";
    private bool editCompactMode;
    private bool saving;
    private string? successMessage;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !saving)
        {
            editTheme = Settings.Theme;
            editFontSize = Settings.FontSize;
            editLanguage = Settings.Language;
            editCompactMode = Settings.CompactMode;
        }
    }

    private async Task SaveAsync()
    {
        saving = true;
        successMessage = null;
        var updated = new AppearanceSettings(editTheme, editFontSize, editLanguage, editCompactMode);
        await OnSave.InvokeAsync(updated);
        successMessage = "Appearance settings saved!";
        saving = false;
    }

    private string BaseFontSize => editFontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private bool IsDark => editTheme == "Dark";

    private string PreviewBgClass => IsDark ? "text-light" : "";
    private string PreviewStyle => $"background-color: {(IsDark ? "#1e1e2e" : "#f8f9fa")}; font-size: {BaseFontSize}; transition: all 0.3s ease;";
    private string PreviewHeadingStyle => $"font-size: {(editFontSize == "Small" ? "1rem" : editFontSize == "Large" ? "1.4rem" : "1.2rem")};";
    private string PreviewTextStyle => $"color: {(IsDark ? "#cdd6f4" : "#333")};";
    private string PreviewBadgeClass => IsDark ? "bg-info" : "bg-primary";
    private string PreviewMutedClass => IsDark ? "text-secondary" : "text-muted";
}

